import {css, html, LitElement} from 'lit'
import {customElement, property} from 'lit/decorators.js'

export type BfLabelTreeNode = {
  label: BfLabel | null
  children: BfLabelTreeNode[]
}

export type BfLabel = {
  id: string
  name: string
  depth: number
  attributes: BfLabelAttributes
}

export type BfLabelAttributes = {
  name: string
  depth: number
  path: string[]
  position: number
}

/**
 * Generic element for a Brandfolder Browser user input/control item.
 */
@customElement('brandfolder-browser-control-item')
export class BfBrowserControlItem extends LitElement {
  static override styles = css`
    fieldset {
      border: 1px solid var(--color-gray-400);
      padding: 0.75rem;
    }
    fieldset legend {
      white-space: nowrap;
    }
  `

  /**
   * Control name/label.
   */
  @property({type: String, attribute: true})
  label: string | null = null

  override render() {
    return html`
      <fieldset
        class="bf-browser-control__inner"
      >
        ${this?.label ? html`<legend>${this.label}</legend>` : 'No Label Provided'}
        <slot></slot>
      </fieldset>
    `
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'brandfolder-browser-control-item': BfBrowserControlItem
  }
}
